INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (1, 'Hypertension', 'A condition characterized by consistently high blood pressure, which can lead to heart disease, stroke, and kidney problems.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (2, 'Diabetes Mellitus', 'A chronic condition where the body cannot properly process glucose, leading to high blood sugar levels, potentially causing complications like neuropathy and cardiovascular disease.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (3, 'Asthma', 'A respiratory condition marked by inflammation and narrowing of the airways, causing difficulty in breathing, wheezing, and coughing.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (4, 'Chronic Kidney Disease', 'A progressive loss of kidney function over time, leading to waste buildup in the body, which can cause complications like hypertension and anemia.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (5, 'Ischemic Heart Disease', 'A condition caused by reduced blood flow to the heart muscle, often due to coronary artery blockage, leading to chest pain and heart attacks.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (6, 'Tuberculosis', 'An infectious disease caused by Mycobacterium tuberculosis, primarily affecting the lungs, causing cough, fever, and weight loss.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (7, 'Dengue Fever', 'A mosquito-borne viral infection causing high fever, severe headache, joint pain, and sometimes hemorrhagic complications.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (8, 'Hepatitis B', 'A viral infection affecting the liver, potentially causing chronic liver disease, cirrhosis, or liver cancer if untreated.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (9, 'Hepatitis C', 'A viral infection of the liver, often chronic, leading to liver damage, cirrhosis, or hepatocellular carcinoma.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (10, 'Anemia', 'A condition where there is a deficiency of red blood cells or hemoglobin, leading to fatigue, weakness, and shortness of breath.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (11, 'Malaria', 'A parasitic infection transmitted by mosquitoes, causing fever, chills, and flu-like symptoms, potentially life-threatening if untreated.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (12, 'Pneumonia', 'An infection of the lungs caused by bacteria, viruses, or fungi, leading to cough, fever, and difficulty breathing.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (13, 'Thalassemia', 'A genetic blood disorder causing abnormal hemoglobin production, leading to anemia and requiring regular blood transfusions.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (14, 'Gastritis', 'Inflammation of the stomach lining, often causing abdominal pain, nausea, and bloating, triggered by infection or irritants.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (15, 'Migraine', 'A neurological condition characterized by recurrent, severe headaches, often accompanied by nausea, vomiting, and sensitivity to light.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (16, 'Arthritis', 'A condition involving inflammation of the joints, causing pain, stiffness, and reduced mobility.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (17, 'Rheumatoid Arthritis', 'An autoimmune disorder causing chronic joint inflammation, pain, and potential joint deformity.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (18, 'Depression', 'A mental health disorder characterized by persistent sadness, loss of interest, and impaired daily functioning.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (19, 'Anxiety Disorder', 'A mental health condition involving excessive worry, fear, or nervousness that interferes with daily life.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (20, 'COVID-19', 'A respiratory illness caused by the SARS-CoV-2 virus, leading to fever, cough, and potentially severe complications.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (21, 'Typhoid', 'A bacterial infection caused by Salmonella typhi, causing high fever, abdominal pain, and weakness.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (22, 'Chickenpox', 'A highly contagious viral infection causing itchy rash and blisters, primarily affecting children.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (23, 'Measles', 'A contagious viral infection causing fever, rash, and respiratory symptoms, preventable by vaccination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (24, 'Mumps', 'A viral infection causing swelling of the salivary glands, fever, and muscle aches, preventable by vaccination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (25, 'Rubella', 'A viral infection causing mild fever, rash, and potential complications in pregnancy, preventable by vaccination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (26, 'Whooping Cough', 'A bacterial respiratory infection causing severe coughing fits, preventable by vaccination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (27, 'Leptospirosis', 'A bacterial infection from contaminated water, causing fever, muscle pain, and potentially severe organ damage.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (28, 'HIV/AIDS', 'A viral infection that weakens the immune system, leading to opportunistic infections and AIDS if untreated.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (29, 'Polio', 'A viral infection that can cause paralysis, primarily affecting children, preventable by vaccination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (30, 'Tetanus', 'A bacterial infection causing muscle stiffness and spasms, often from wounds, preventable by vaccination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (31, 'Cholera', 'A bacterial infection causing severe diarrhea and dehydration, often from contaminated water.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (32, 'Scabies', 'A contagious skin condition caused by mites, leading to intense itching and rash.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (33, 'Ringworm', 'A fungal skin infection causing circular, itchy rashes, treatable with antifungal medications.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (34, 'Fungal Skin Infection', 'Infections caused by fungi, leading to itchy, scaly rashes on the skin or nails.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (35, 'Eczema', 'A chronic skin condition causing inflamed, itchy, and dry skin patches.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (36, 'Psoriasis', 'A chronic autoimmune condition causing rapid skin cell buildup, resulting in scaly patches.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (37, 'Cystic Fibrosis', 'A genetic disorder affecting the lungs and digestive system, causing mucus buildup and infections.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (38, 'Sickle Cell Anemia', 'A genetic disorder causing abnormal red blood cells, leading to pain and infections.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (39, 'Hemophilia', 'A genetic disorder impairing blood clotting, leading to prolonged bleeding and bruising.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (40, 'Hypothyroidism', 'A condition where the thyroid gland produces insufficient hormones, causing fatigue and weight gain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (41, 'Hyperthyroidism', 'A condition where the thyroid gland produces excessive hormones, causing weight loss and rapid heartbeat.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (42, 'Obesity', 'A condition characterized by excessive body fat, increasing the risk of diabetes and heart disease.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (43, 'Metabolic Syndrome', 'A cluster of conditions increasing the risk of heart disease, stroke, and diabetes.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (44, 'Gout', 'A form of arthritis caused by uric acid buildup, leading to sudden, severe joint pain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (45, 'Lupus', 'An autoimmune disease causing inflammation in various organs, leading to fatigue and joint pain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (46, 'Multiple Sclerosis', 'A chronic autoimmune disease affecting the central nervous system, causing muscle weakness and coordination issues.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (47, 'Parkinson’s Disease', 'A neurodegenerative disorder affecting movement, causing tremors and stiffness.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (48, 'Alzheimer’s Disease', 'A progressive neurodegenerative disorder causing memory loss and cognitive decline.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (49, 'Cervical Cancer', 'A cancer of the cervix, often linked to HPV infection, detectable through screening.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (50, 'Breast Cancer', 'A malignant tumor in the breast tissue, often detected through mammography or self-examination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (51, 'Lung Cancer', 'A malignant tumor in the lungs, often linked to smoking, causing cough and weight loss.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (52, 'Oral Cancer', 'A cancer of the mouth or throat, often linked to tobacco use, causing sores and pain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (53, 'Skin Cancer', 'A cancer of the skin, often caused by UV exposure, presenting as abnormal skin growths.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (54, 'Colon Cancer', 'A cancer of the colon or rectum, often detected through colonoscopy, causing changes in bowel habits.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (55, 'Pancreatic Cancer', 'A cancer of the pancreas, often diagnosed late, causing abdominal pain and weight loss.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (56, 'Prostate Cancer', 'A cancer of the prostate gland, often detected through PSA testing, causing urinary issues.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (57, 'Brain Tumor', 'A growth in the brain, causing headaches, seizures, and neurological symptoms.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (58, 'GERD', 'A chronic condition where stomach acid flows back into the esophagus, causing heartburn.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (59, 'Peptic Ulcer', 'Sores in the stomach or duodenum lining, causing burning abdominal pain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (60, 'IBS', 'A functional gastrointestinal disorder causing abdominal pain, bloating, and altered bowel habits.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (61, 'Crohn’s Disease', 'A chronic inflammatory bowel disease causing abdominal pain, diarrhea, and weight loss.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (62, 'Ulcerative Colitis', 'A chronic inflammatory bowel disease causing ulcers in the colon, leading to diarrhea and pain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (63, 'Cirrhosis', 'A late-stage liver disease caused by scarring, leading to liver dysfunction and jaundice.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (64, 'Fatty Liver Disease', 'A condition caused by fat buildup in the liver, potentially leading to liver damage.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (65, 'Gallstones', 'Hardened deposits in the gallbladder, causing pain and digestive issues.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (66, 'Urinary Tract Infection', 'An infection in the urinary system, causing pain during urination and frequent urges.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (67, 'Kidney Stones', 'Hard deposits in the kidneys, causing severe pain and urinary issues.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (68, 'Glomerulonephritis', 'Inflammation of the kidney’s filtering units, leading to blood in urine and kidney damage.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (69, 'Nephrotic Syndrome', 'A kidney disorder causing excessive protein loss in urine, leading to swelling.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (70, 'UTI', 'An infection in the urinary tract, causing burning sensation during urination and frequent urination.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (71, 'Otitis Media', 'An infection or inflammation of the middle ear, causing ear pain and fever.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (72, 'Sinusitis', 'Inflammation of the sinuses, causing nasal congestion, headache, and facial pain.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (73, 'Conjunctivitis', 'Inflammation of the conjunctiva, causing red, itchy eyes and discharge.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (74, 'Tonsillitis', 'Inflammation of the tonsils, causing sore throat and difficulty swallowing.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (75, 'Bronchitis', 'Inflammation of the bronchial tubes, causing cough and mucus production.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (76, 'Influenza', 'A viral respiratory infection causing fever, body aches, and fatigue.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (77, 'Zika Virus Infection', 'A mosquito-borne viral infection causing mild fever, rash, and potential birth defects.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (78, 'Ebola Virus Disease', 'A severe viral infection causing fever, bleeding, and high mortality rates.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (79, 'Scrub Typhus', 'A bacterial infection from mites, causing fever, rash, and organ complications.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (80, 'Rickettsial Infections', 'Bacterial infections from ticks or mites, causing fever and rash.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (81, 'Lassa Fever', 'A viral hemorrhagic fever causing fever, bleeding, and organ failure.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (82, 'Hantavirus Infection', 'A viral infection from rodents, causing fever and severe respiratory distress.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (83, 'Plague', 'A bacterial infection causing fever, swollen lymph nodes, and potentially severe complications.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (84, 'Rabies', 'A viral infection from animal bites, causing neurological symptoms and nearly always fatal if untreated.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (85, 'Hydrocephalus', 'A condition involving fluid buildup in the brain, causing increased pressure and neurological symptoms.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (86, 'Spina Bifida', 'A congenital defect where the spine and spinal cord do not form properly, causing mobility issues.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (87, 'Epilepsy', 'A neurological disorder causing recurrent seizures due to abnormal brain activity.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (88, 'Stroke', 'A sudden interruption of blood flow to the brain, causing neurological deficits like paralysis.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (89, 'Transient Ischemic Attack', 'A temporary blockage of blood flow to the brain, causing stroke-like symptoms that resolve quickly.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (90, 'Glaucoma', 'A group of eye conditions causing optic nerve damage, leading to vision loss.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (91, 'Cataract', 'Clouding of the eye’s lens, causing blurred vision and potential blindness if untreated.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (92, 'Macular Degeneration', 'A condition affecting the retina, causing central vision loss, often age-related.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (93, 'Retinopathy', 'Damage to the retina’s blood vessels, often due to diabetes, causing vision impairment.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (94, 'Autism Spectrum Disorder', 'A developmental disorder affecting communication, behavior, and social interaction.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (95, 'ADHD', 'A neurodevelopmental disorder causing difficulty in sustaining attention and controlling impulses.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (96, 'Schizophrenia', 'A mental disorder causing hallucinations, delusions, and disordered thinking.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (97, 'Bipolar Disorder', 'A mental health condition causing extreme mood swings, from mania to depression.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (98, 'Dysthymia', 'A chronic form of depression with less severe but persistent symptoms.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (99, 'Insomnia', 'A sleep disorder causing difficulty falling or staying asleep, impacting daily functioning.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (100, 'Sleep Apnea', 'A sleep disorder causing repeated breathing interruptions, leading to poor sleep and fatigue.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (101, 'Anorexia Nervosa', 'An eating disorder characterized by extreme weight loss and fear of gaining weight.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (102, 'Bulimia', 'An eating disorder involving binge eating followed by purging behaviors.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (103, 'Osteoporosis', 'A condition causing weakened bones, increasing the risk of fractures.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (104, 'Vitiligo', 'A condition causing loss of skin pigment, resulting in white patches on the skin.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (105, 'Melanoma', 'A serious form of skin cancer arising from melanocytes, often linked to UV exposure.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (106, 'Hemorrhoids', 'Swollen veins in the rectum or anus, causing pain and discomfort.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (107, 'Anal Fissure', 'A small tear in the anus lining, causing pain and bleeding during bowel movements.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (108, 'Pelvic Inflammatory Disease', 'An infection of the female reproductive organs, causing pelvic pain and infertility risk.');
INSERT INTO public.diseases (disease_id, disease_name, description) VALUES (109, 'Endometriosis', 'A condition where tissue similar to the uterine lining grows outside the uterus, causing pelvic pain.');
